insert into price_checks values('anonymous save denied by grant',not has_function_privilege('anon','public.yesmoa_price_save(text,numeric,bigint)','execute'));
insert into price_checks values('authenticated direct table updates denied',not has_table_privilege('authenticated','public.yesmoa_prices','update'));
insert into price_checks values('history private',not has_table_privilege('anon','public.yesmoa_price_history','select') and not has_table_privilege('authenticated','public.yesmoa_price_history','select'));
insert into public.yesmoa_prices(id,kind,category,name,unit,sort_order,price) values('__transaction_test__','normal','TEST','Transaction only test','EA',999999,10);
select set_config('yesmoa_test.admin',(select user_id::text from yesmoa_private.admins limit 1),true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
set local role authenticated;
do $check$ begin
 begin perform public.yesmoa_price_save('__transaction_test__',20,1);raise exception 'REGULAR WRITE ALLOWED';exception when insufficient_privilege then null;end;
end;$check$;
reset role;
insert into price_checks values('regular user save denied',true);
select set_config('request.jwt.claim.sub',current_setting('yesmoa_test.admin'),true);
set local role authenticated;
do $check$ declare r jsonb; begin
 r:=public.yesmoa_price_save('__transaction_test__',0,1);if r->>'price'<>'0' then raise exception 'zero failed';end if;
 r:=public.yesmoa_price_save('__transaction_test__',null,2);if r->'price'<>'null'::jsonb then raise exception 'null failed';end if;
 begin perform public.yesmoa_price_save('__transaction_test__',12,1);raise exception 'CONFLICT ACCEPTED';exception when raise_exception then if sqlerrm<>'Price conflict' then raise;end if;end;
 begin perform public.yesmoa_price_save('__transaction_test__',-1,3);raise exception 'NEGATIVE ACCEPTED';exception when raise_exception then if sqlerrm<>'Invalid price' then raise;end if;end;
 begin perform public.yesmoa_price_save('__transaction_test__',1.5,3);raise exception 'DECIMAL ACCEPTED';exception when raise_exception then if sqlerrm<>'Invalid price' then raise;end if;end;
end;$check$;
reset role;
insert into price_checks values('admin zero/null/conflict/negative/decimal',true);
insert into price_checks select 'audit history records admin and before/after',count(*)=2 and bool_and(changed_by=current_setting('yesmoa_test.admin')::uuid) from public.yesmoa_price_history where product_id='__transaction_test__';
select * from price_checks;
rollback;
